#!/bin/bash
export AGENT_BROWSER_SESSION="zt7014v2"
LOG="$TEMP/zt7014/verify_chart.log"
: > "$LOG"
cat > "$TEMP/zt7014/vc.js" <<'JS'
(() => {
  const legend = Array.from(document.querySelectorAll('*')).find(e => e.children.length===0 && (e.textContent||'').trim()==='资金总额');
  let card = legend;
  for(let i=0;i<6 && card;i++){ card = card.parentElement; if(card && card.querySelector('svg')) break; }
  const svg = card ? card.querySelector('svg') : null;
  const rects = svg ? svg.querySelectorAll('rect').length : 0;
  const lines = svg ? svg.querySelectorAll('line').length : 0;
  const paths = svg ? svg.querySelectorAll('path').length : 0;
  const polys = svg ? svg.querySelectorAll('polyline,polygon').length : 0;
  const swatches = card ? Array.from(card.querySelectorAll('[class*=trend-swatch],[class*=trend-bar],[class*=trend-line]')).map(e=>e.className).slice(0,20) : [];
  const cardText = card ? card.innerText.slice(0,300) : 'NO CARD';
  // 旧数字卡片特征：带括号单位或千分位数值
  const oldNumPattern = /开户主体数（个）|公共收益资金总额（万元）|1,197/;
  return JSON.stringify({svgFound: !!svg, rects, lines, paths, polys, swatches, oldNumStillThere: oldNumPattern.test(cardText), cardText});
})()
JS
agent-browser eval --stdin < "$TEMP/zt7014/vc.js" >> "$LOG" 2>&1
echo "DONE" >> "$LOG"
EOF
bash verify_chart.sh; echo "=== verify_chart.log ==="; cat verify_chart.log

